// Street-name fuzzy matching against a dictionary of real Tampa/Hillsborough
// streets (shared/tampa-street-dictionary.json, generated by
// scripts/generate-street-dictionary.ts). Pure functions only — no I/O, no
// geocoding. Callers (server/routes.ts) verify suggestions by geocoding before
// trusting them.

export interface StreetDictionary {
  generatedAt: string;
  source: string;
  names: string[];
  /** normalized stem -> canonical display name ("habana" -> "Habana Ave") */
  stems: Record<string, string>;
}

export interface StreetSuggestion {
  /** canonical street name, e.g. "Habana Ave" */
  name: string;
  /** 0..1 */
  score: number;
  /** the normalized query stem this answers */
  matchedStem: string;
  /** full corrected address preserving block number / directional */
  correctedAddress: string;
}

export function levenshtein(a: string, b: string): number {
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(
        prev[j] + 1,
        cur[j - 1] + 1,
        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),
      );
    }
    prev = cur;
  }
  return prev[b.length];
}

const SUFFIXES = new Set([
  "st", "street", "ave", "avenue", "rd", "road", "blvd", "boulevard", "dr",
  "drive", "ln", "lane", "ct", "court", "cir", "circle", "hwy", "highway",
  "pkwy", "parkway", "pl", "place", "ter", "terrace", "trl", "trail", "way",
  "expy", "expressway", "run", "path", "row", "rdg", "ridge", "cove", "loop",
  "alley", "bridge", "causeway", "crossing", "walk",
]);
const SINGLE_DIR = new Set(["n", "s", "e", "w", "ne", "nw", "se", "sw"]);
const MULTI_DIR = new Set(["north", "south", "east", "west"]);
const ORDINAL_WORDS: Record<string, string> = {
  first: "1st", second: "2nd", third: "3rd", fourth: "4th", fifth: "5th",
  sixth: "6th", seventh: "7th", eighth: "8th", ninth: "9th", tenth: "10th",
  eleventh: "11th", twelfth: "12th", thirteenth: "13th", fourteenth: "14th",
  fifteenth: "15th", sixteenth: "16th", seventeenth: "17th",
  eighteenth: "18th", nineteenth: "19th", twentieth: "20th",
};
// Speech filler that leaks into extracted addresses ("I'm gonna back alley").
const FILLER = new Set(["gonna", "wanna", "kinda", "sorry", "thank", "thanks", "excuse", "welcome", "live", "stream", "youtube", "um", "uh"]);
const INTERSECTION_SPLIT_RE = /\s+(?:and|amd|an|at|on|&|@)\s+/i;
const NUMBERED_STEM_RE = /^\d+(?:st|nd|rd|th)$/;

const MIN_SCORE = 0.75;
const MIN_MARGIN = 0.08;
const INTERSECTION_MIN = 0.9;

/** Shared normalization for dictionary names and query segments. */
export function normalizeStreet(input: string): string {
  const tokens = input
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .map((t) => ORDINAL_WORDS[t] ?? t);
  if (tokens.length > 1 && SINGLE_DIR.has(tokens[0])) tokens.shift();
  if (tokens.length > 1 && SUFFIXES.has(tokens[tokens.length - 1])) tokens.pop();
  return tokens.join(" ");
}

export interface AddressSegment {
  stem: string;
  block: string | null;
  dir: string | null;
}

/** Split an address into intersection segments with block/directional kept. */
export function extractAddressSegments(address: string): AddressSegment[] {
  return address
    .split(INTERSECTION_SPLIT_RE)
    .map((part) => {
      const tokens = part
        .toLowerCase()
        .replace(/[^a-z0-9\s]/g, " ")
        .split(/\s+/)
        .filter(Boolean)
        .filter((t) => !FILLER.has(t));
      let block: string | null = null;
      let dir: string | null = null;
      while (tokens.length && /^\d+$/.test(tokens[0])) {
        block = block ? `${block} ${tokens[0]}` : tokens[0];
        tokens.shift();
      }
      if (tokens.length && MULTI_DIR.has(tokens[0])) {
        dir = tokens[0];
        tokens.shift();
      }
      if (tokens.length && SINGLE_DIR.has(tokens[0])) {
        dir = tokens[0];
        tokens.shift();
      }
      return { block, dir, stem: normalizeStreet(tokens.join(" ")) };
    })
    .filter((seg) => seg.stem.length >= 3);
}

/** Suggest a canonical street for ONE normalized stem. Zero or one result. */
export function suggestForStem(
  stem: string,
  dict: StreetDictionary,
): { name: string; score: number; matchedStem: string } | null {
  if (!stem || stem.length < 3 || !dict) return null;
  // Numbered streets must match digits exactly — "50th" never suggests "56th".
  if (NUMBERED_STEM_RE.test(stem)) {
    const exact = dict.stems[stem];
    return exact ? { name: exact, score: 1, matchedStem: stem } : null;
  }
  const exact = dict.stems[stem];
  if (exact) return { name: exact, score: 1, matchedStem: stem };

  let best: { name: string; score: number; matchedStem: string } | null = null;
  let second = 0;
  for (const [dStem, name] of Object.entries(dict.stems)) {
    const fuzzy = 1 - levenshtein(stem, dStem) / Math.max(stem.length, dStem.length);
    // Containment only counts when the shorter side covers most of the
    // longer — otherwise a common substring ("back" inside "i m back alley")
    // rubber-stamps garbage at 0.9.
    const shorter = Math.min(stem.length, dStem.length);
    const longer = Math.max(stem.length, dStem.length);
    const containment =
      shorter / longer >= 0.7 && (stem.includes(dStem) || dStem.includes(stem)) ? 0.9 : 0;
    const score = Math.max(fuzzy, containment);
    if (!best || score > best.score) {
      second = best ? best.score : 0;
      best = { name, score, matchedStem: stem };
    } else if (score > second) {
      second = score;
    }
  }
  if (!best || best.score < MIN_SCORE) return null;
  if (best.score < 1 && best.score - second < MIN_MARGIN) return null;
  return best;
}

function rebuildSegment(seg: AddressSegment, canonicalName: string): string {
  return [seg.block, seg.dir, canonicalName].filter(Boolean).join(" ");
}

/**
 * Suggest a corrected address for a garbled/unresolved one. Single-segment
 * addresses accept the best match at >= MIN_SCORE; intersections require both
 * sides to clear INTERSECTION_MIN; anything more complex is left alone.
 */
export function suggestStreets(
  address: string,
  dict: StreetDictionary | null,
): StreetSuggestion[] {
  if (!address || !dict) return [];
  const segs = extractAddressSegments(address);
  if (segs.length === 0 || segs.length > 2) return [];
  const perSeg = segs.map((seg) => ({ seg, hit: suggestForStem(seg.stem, dict) }));
  if (perSeg.some((p) => !p.hit)) return [];
  if (segs.length === 2 && perSeg.some((p) => (p.hit?.score ?? 0) < INTERSECTION_MIN)) {
    return [];
  }
  const corrected =
    segs.length === 1
      ? rebuildSegment(perSeg[0].seg, perSeg[0].hit!.name)
      : `${rebuildSegment(perSeg[0].seg, perSeg[0].hit!.name)} & ${rebuildSegment(perSeg[1].seg, perSeg[1].hit!.name)}`;
  // A "correction" that changes nothing means the original already matched the
  // dictionary verbatim — usually a junk address that happens to BE a real
  // street name ("E Street"). Geocoding it again adds nothing the dispatch
  // path didn't already try; leave it quarantined.
  if (normalizeStreet(corrected) === normalizeStreet(address)) return [];
  const score = Math.min(...perSeg.map((p) => p.hit!.score));
  return [
    {
      name: perSeg[0].hit!.name,
      score: Math.round(score * 100) / 100,
      matchedStem: perSeg[0].hit!.matchedStem,
      correctedAddress: corrected,
    },
  ];
}
